{
  "name": "opencode-docker-panel",
  "version": "0.7.1",
  "description": "Docker container panel for the OpenCode 2 TUI sidebar",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "docker",
    "docker-compose",
    "sidebar",
    "tui"
  ],
  "homepage": "https://github.com/victor-ochenin/opencodeDockerPlugin#readme",
  "bugs": {
    "url": "https://github.com/victor-ochenin/opencodeDockerPlugin/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/victor-ochenin/opencodeDockerPlugin.git",
    "directory": "."
  },
  "type": "module",
  "license": "MIT",
  "exports": {
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "node --experimental-strip-types scripts/build.ts",
    "check": "node --experimental-strip-types scripts/check-parser.ts",
    "typecheck": "tsc --noEmit",
    "check-build": "node --experimental-strip-types scripts/check-build.ts",
    "format": "prettier --write .",
    "format:check": "prettier --check ."
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.0.20",
    "@opencode/theme": "^2.0.20",
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": "^1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opencode/theme": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@babel/core": "^7.28.0",
    "@babel/preset-typescript": "^7.27.1",
    "@opencode/plugin": "^2.0.20",
    "@opencode/theme": "^2.0.20",
    "@opentui/core": "0.5.12",
    "@opentui/solid": "0.5.12",
    "@types/babel__core": "^7.20.5",
    "babel-preset-solid": "^1.9.12",
    "prettier": "^3.9.9",
    "solid-js": "1.9.12",
    "typescript": "^5.9.2"
  }
}
